function LiveMarksPage({profile,toast}:{profile:Profile;toast:(s:string)=>void}){const isStudent=profile.role==='student';const courses=useQuery({queryKey:['grade-courses',profile.role],queryFn:()=>api<any>('/courses'),enabled:supabaseConfigured&&!isStudent});const marks=useQuery({queryKey:['marks',profile.role,(courses.data?.data||[]).map((c:any)=>c.id).join(',')],queryFn:async()=>isStudent?api<any>('/marks/me'):Promise.all((courses.data?.data||[]).map(async(c:any)=>{const rows=await api<any>(`/courses/${c.id}/marks`);return rows.map((m:any)=>({...m,course:c.title}))})).then(parts=>parts.flat()),enabled:supabaseConfigured&&(isStudent||Boolean(courses.data?.data?.length))});const [filter,setFilter]=useState('All types');const rows=supabaseConfigured?(marks.data||[]).map((m:any)=>({title:m.title,type:capitalize(m.item_type),course:typeof m.course==='string'?m.course:m.course?.title||'Course',mark:m.status==='Pending'?'Pending':`${m.marks_obtained} / ${m.max_marks}`,pct:Number(m.percentage)||0,pending:m.status==='Pending',score:Number(m.marks_obtained)||0,max:Number(m.max_marks)||0,student:m.student?.full_name||'',gradedAt:m.graded_at})):markRows;const filtered=rows.filter((m:any)=>filter==='All types'||m.type===filter);const gradedRows=rows.filter((m:any)=>!m.pending);const totalMarks=gradedRows.reduce((sum:number,m:any)=>sum+(m.score||0),0),totalMax=gradedRows.reduce((sum:number,m:any)=>sum+(m.max||0),0),avg=totalMax?totalMarks/totalMax*100:(gradedRows.length?gradedRows.reduce((sum:number,m:any)=>sum+m.pct,0)/gradedRows.length:0);function exportCsv(){if(!isStudent&&rows.length){const csv=['Student,Course,Item,Type,Marks,Percentage',...rows.map((m:any)=>[m.student,m.course,m.title,m.type,m.mark,m.pct].map((v:any)=>`"${String(v||'').replaceAll('"','""')}"`).join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download='course-gradebook.csv';link.click();URL.revokeObjectURL(url);return}toast('Your marks are up to date.')}return <><div className="page-heading"><div><span className="eyebrow">YOUR PROGRESS, IN PERSPECTIVE</span><h1>{isStudent?'Marks & feedback':'Course gradebook'}</h1><p>{isStudent?'Every mark is a moment of progress. Here’s how you’re doing.':'A clear view of how your students are growing.'}</p></div><button className="button button-outline" onClick={exportCsv}><ArrowDownRight size={16}/>{isStudent?'Download report':'Export CSV'}</button></div>{marks.isLoading?<div className="loading-card surface">Gathering your marks…</div>:<><div className="marks-summary-grid"><div className="surface marks-score"><span className="eyebrow">{isStudent?'OVERALL AVERAGE':'ITEM AVERAGE'}</span><div className="score-line"><strong>{(supabaseConfigured?avg:88.7).toFixed(1).split('.')[0]}<span>.{(supabaseConfigured?avg:88.7).toFixed(1).split('.')[1]}</span></strong><span className="score-outof">%<small>{isStudent?'across all courses':'graded items'}</small></span><span className="score-change"><ArrowUpRight size={14}/> {isStudent?'On track':'Updated'}</span></div><div className="progress-track"><i style={{width:`${supabaseConfigured?avg:88.7}%`}}/></div><small className="muted">Only graded work is included in totals.</small></div><div className="surface marks-stat"><span className="stat-icon lavender"><FileCheck2 size={17}/></span><span className="eyebrow">GRADED ITEMS</span><strong>{supabaseConfigured?gradedRows.length:14} <small>{isStudent?'results':'records'}</small></strong><span className="muted">Pending work is not included</span></div><div className="surface marks-stat"><span className="stat-icon mint"><Sparkles size={17}/></span><span className="eyebrow">PERSONAL BEST</span><strong>{Math.max(0,...gradedRows.map((m:any)=>m.pct))}<small>%</small></strong><span className="muted">Highest graded percentage</span></div></div><section className="surface marks-table-surface"><div className="section-head"><div><span className="eyebrow">RECENT RESULTS</span><h2>{isStudent?'Marks by course':'Student results'}</h2></div><select value={filter} onChange={e=>setFilter(e.target.value)} className="select-filter"><option>All types</option><option>Assignment</option><option>Quiz</option></select></div><div className="mark-course-groups">{filtered.map((m:any,i:number)=><div className="mark-row" key={`${m.title}-${i}`}><span className={`mark-course-icon ${['plum','blue','orange'][i%3]}`}><BookOpen size={16}/></span><div className="mark-title"><strong>{isStudent?m.title:`${m.student||'Student'} · ${m.title}`}</strong><small>{m.course} · {m.type}</small></div><div className="mark-progress"><div><span>{m.pct}%</span><b>{m.mark}</b></div><i><em style={{width:`${m.pct}%`}}/></i></div>{isStudent&&<button className="text-action feedback-button" onClick={()=>toast('Check the assignment for your teacher’s feedback.')}>Details <ArrowRight size={14}/></button>}</div>)}</div>{!filtered.length&&<div className="empty-state"><Activity/><h3>No graded items yet</h3><p>Once your teacher grades work, the results will appear here.</p></div>}</section></>}</>}

